    83→// Helper function to format time ago
    84→const formatTimeAgo = (date: Date | string) => {
    85→  const now = new Date();
    86→  const d = new Date(date);
    87→  const diff = Math.floor((now.getTime() - d.getTime()) / 1000);
    88→  if (diff < 60) return "Just now";
    89→  if (diff < 3600) return `${Math.floor(diff / 60)} mins ago`;
    90→  if (diff < 86400) return `${Math.floor(diff / 3600)} hours ago`;
    91→  return d.toLocaleDateString();
    92→};
